/**
 * Golden reference cases (`test/golden/*.csv`, generated by `scripts/golden*.py`)
 * and the harness that runs a definition over one and compares. Shared by the
 * built-in golden tests and the user-script golden reuse tests.
 */
import { readdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { expect } from 'vitest';
import type { AnyIndicatorDefinition, IndicatorRegistry } from '../src/registry';
import { isValueOutput, resolveInputs, timeframeInputValue } from '../src/resolve';
import { IndicatorRuntime } from '../src/runtime';
import {
  NO_COLOR,
  type BarArrays,
  type FundamentalsData,
  type IndicatorResult,
  type InputValueMap,
} from '../src/types';
import { dailyBars, feedLive, snapshot, toColumns } from './helpers';

const DIR = join(dirname(fileURLToPath(import.meta.url)), 'golden');

export interface GoldenCsv {
  inputs: InputValueMap;
  ref: string;
  /** Bar series file the case runs on (header ` bars: <file>`, default bars.csv). */
  bars: string;
  /** Second aligned series (header ` extra: <file>`), e.g. Correlation's symbol. */
  extra: string | null;
  /** Statements fixture JSON (header ` fund: <file>`), financial built-ins only. */
  fund: string | null;
  cols: Record<string, Float64Array>;
}

export function parseCsv(file: string): GoldenCsv {
  const lines = readFileSync(join(DIR, file), 'utf8').trimEnd().split('\n');
  let inputs: InputValueMap = {};
  let ref = '';
  let barsFile = 'bars.csv';
  let extra: string | null = null;
  let fund: string | null = null;
  if (lines[0]!.startsWith('#')) {
    const m =
      /^# inputs: (\{.*\}) ref: (\w+)(?: bars: ([\w.-]+))?(?: extra: ([\w.-]+))?(?: fund: ([\w.-]+))?$/.exec(
        lines.shift()!,
      );
    if (!m) throw new Error(`${file}: bad header`);
    inputs = JSON.parse(m[1]!) as InputValueMap;
    ref = m[2]!;
    barsFile = m[3] ?? barsFile;
    extra = m[4] ?? null;
    fund = m[5] ?? null;
  }
  const names = lines.shift()!.split(',');
  const cols: Record<string, Float64Array> = {};
  for (const name of names) cols[name] = new Float64Array(lines.length);
  lines.forEach((line, i) => {
    line.split(',').forEach((cell, k) => {
      cols[names[k]!]![i] = cell === '' ? NaN : Number(cell);
    });
  });
  return { inputs, ref, bars: barsFile, extra, fund, cols };
}

/** Bar series files (`bars*.csv`, no header), loaded once. */
const series = new Map<string, BarArrays>();
function barsOf(file: string): BarArrays {
  let b = series.get(file);
  if (!b) {
    b = parseCsv(file).cols as unknown as BarArrays;
    series.set(file, b);
  }
  return b;
}

/** Statements fixture (ISO period ends, null = missing) in runtime form, loaded once. */
const funds = new Map<string, FundamentalsData>();
function fundOf(file: string): FundamentalsData {
  let f = funds.get(file);
  if (!f) {
    const raw = JSON.parse(readFileSync(join(DIR, file), 'utf8')) as {
      quarterly?: RawBasis;
      annual?: RawBasis;
    };
    f = {
      quarterly: raw.quarterly && basis(raw.quarterly),
      annual: raw.annual && basis(raw.annual),
    } as FundamentalsData;
    funds.set(file, f);
  }
  return f;
}

interface RawStatement {
  periods: string[];
  rows: Record<string, (number | null)[]>;
}
type RawBasis = Partial<Record<'income' | 'balance' | 'cashflow', RawStatement>>;

function basis(raw: RawBasis): Partial<Record<'income' | 'balance' | 'cashflow', unknown>> {
  const out: Record<string, unknown> = {};
  for (const [kind, stmt] of Object.entries(raw)) {
    if (!stmt || !stmt.periods?.length) continue;
    out[kind] = {
      periods: stmt.periods.map((p) => Date.parse(p) / 1000),
      rows: Object.fromEntries(
        Object.entries(stmt.rows).map(([name, values]) => [
          name,
          values.map((v) => (v === null || v === undefined ? NaN : v)),
        ]),
      ),
    };
  }
  return out;
}

/** Bar interval of a series: its smallest time step. */
function intervalOf(bars: BarArrays): number {
  let step = Infinity;
  for (let i = 1; i < bars.time.length; i++)
    step = Math.min(step, bars.time[i]! - bars.time[i - 1]!);
  return Number.isFinite(step) ? step : 0;
}

/** Case names (file names without `.csv`), sorted. */
export const GOLDEN_CASES = readdirSync(DIR)
  .filter((f) => f.endsWith('.csv') && !f.startsWith('bars'))
  .map((f) => f.slice(0, -4))
  .sort();

/** True if golden case `name` belongs to indicator id `id` (`<id>` or `<id>-...`). */
export function isCaseOf(name: string, id: string): boolean {
  return name === id || name.startsWith(`${id}-`);
}

/**
 * Runs `def` (registered under `def.id` in `registry`, default registry if
 * omitted) over the case's bars, all at once or (`live`) as history up to
 * bar 500 followed by live ticks and appends.
 */
export function runGolden(
  def: AnyIndicatorDefinition,
  csv: GoldenCsv,
  live: boolean,
  registry?: IndicatorRegistry,
): IndicatorResult {
  const { inputs } = csv;
  const bars = barsOf(csv.bars);
  const tf = timeframeInputValue(def, resolveInputs(def, inputs));
  if (tf && tf !== '1D') throw new Error(`golden tests only aggregate 1D bars, got ${tf}`);
  const rt = new IndicatorRuntime({
    ...(registry ? { registry } : {}),
    context: {
      intervalSeconds: intervalOf(bars),
      timeframeSeconds: { '1D': 86_400 },
      ...(csv.fund ? { fundamentals: fundOf(csv.fund) } : {}),
    },
  });
  rt.add({ id: 'x', type: def.id, inputs });
  // The case's second series is the external symbol its `symbol` input names.
  const external = csv.extra ? { [String(inputs['symbol'])]: barsOf(csv.extra) } : {};
  if (live) feedLive(rt, bars, 500, tf, external);
  else {
    rt.setBars(bars);
    for (const [symbol, ext] of Object.entries(external)) rt.setExternal(symbol, ext);
    if (tf) rt.setTimeframeBars(tf, toColumns(dailyBars(bars)));
  }
  const r = rt.result('x')!;
  expect(r.status).toEqual({ state: 'ok' });
  expect(r.length).toBe(bars.time.length);
  return r;
}

function close(a: number, b: number): boolean {
  if (Number.isNaN(b)) return Number.isNaN(a);
  return Math.abs(a - b) <= 1e-8 * Math.max(1, Math.abs(b));
}

export interface GoldenCompareOptions {
  /**
   * Palette indices are only compared on bars where the reference value is
   * defined; on NaN bars the index must be `NO_COLOR` (scripts that hide
   * warm-up bars, where the reference has whatever index its formula gives).
   */
  noColorOnNaN?: boolean;
}

/**
 * Asserts that `def`'s full computation on case `name` matches the reference
 * (every value output and palette covered, values within 1e-8 relative,
 * palette indices exact) and that live ticks give identical arrays.
 */
export function expectGolden(
  name: string,
  def: AnyIndicatorDefinition,
  registry?: IndicatorRegistry,
  opts: GoldenCompareOptions = {},
): void {
  const csv = parseCsv(`${name}.csv`);
  const { cols } = csv;
  const full = runGolden(def, csv, false, registry);

  // Every value output and every palette is covered by the reference.
  const valueIds = def.outputs.filter(isValueOutput).map((o) => o.id);
  const refCols = Object.keys(cols).filter((k) => k !== 'time');
  expect(refCols.filter((k) => !k.endsWith('.color')).sort()).toEqual(valueIds.sort());
  for (const id of Object.keys(full.colors)) expect(refCols).toContain(`${id}.color`);

  for (const col of refCols) {
    const ref = cols[col]!;
    const colorOf = col.endsWith('.color') ? col.slice(0, -'.color'.length) : null;
    const got = colorOf ? full.colors[colorOf]! : full.values[col]!;
    const refValue = colorOf ? cols[colorOf]! : null;
    const bad: string[] = [];
    for (let i = 0; i < ref.length; i++) {
      let want = ref[i]!;
      if (opts.noColorOnNaN && refValue && Number.isNaN(refValue[i]!)) want = NO_COLOR;
      const ok = colorOf ? got[i] === want : close(got[i]!, want);
      if (!ok && bad.length < 5) bad.push(`[${i}] got ${got[i]} want ${want}`);
    }
    expect(bad, `${name}.${col}`).toEqual([]);
  }

  // Live ticks and appends from bar 500 give identical arrays.
  expect(snapshot(runGolden(def, csv, true, registry))).toEqual(snapshot(full));
}
